import apiClient from './client'

export interface RemoteAction {
  action_id: string
  name: string
  risk_level: string
}

export interface RemoteExecutionCreate {
  node_ids: string[]
  action_id: string
  action_params: Record<string, unknown>
  timeout?: number
  confirmed: boolean
}

export interface RemoteExecutionCreateResponse {
  execution_ids: string[]
  status: string
}

export interface RemoteExecutionRead {
  id: number
  execution_id: string
  node_id: string
  user_id: number
  action_id: string
  action_params: Record<string, unknown>
  status: string
  output?: string | null
  error_message?: string | null
  timeout_seconds: number
  started_at?: string | null
  finished_at?: string | null
  created_at: string
  updated_at: string
}

export async function getRemoteActions(): Promise<RemoteAction[]> {
  const response = await apiClient.get<{ actions: RemoteAction[] }>('/v1/remote-actions')
  return response.data.actions
}

export async function createRemoteExecution(
  data: RemoteExecutionCreate,
): Promise<RemoteExecutionCreateResponse> {
  const response = await apiClient.post<RemoteExecutionCreateResponse>('/v1/remote-executions', data)
  return response.data
}

export async function listRemoteExecutions(params?: {
  node_id?: string
  status?: string
}): Promise<RemoteExecutionRead[]> {
  const response = await apiClient.get<RemoteExecutionRead[]>('/v1/remote-executions', { params })
  return response.data
}

export async function getRemoteExecution(executionId: string): Promise<RemoteExecutionRead> {
  const response = await apiClient.get<RemoteExecutionRead>(`/v1/remote-executions/${executionId}`)
  return response.data
}
