<template>
  <div class="page-remote-execute">
    <CrudToolbar
      :title="t('remote.title')"
      :create-text="t('remote.createExecution')"
      :can-create="authStore.isAdmin"
      @create="onCreate"
    />

    <el-alert
      v-if="!authStore.isAdmin"
      :title="t('remote.adminOnly')"
      type="info"
      show-icon
      :closable="false"
      style="margin-bottom: 16px"
    />

    <el-card style="margin-bottom: 16px">
      <el-form :model="filters" :inline="true">
        <el-form-item :label="t('common.node')">
          <el-input v-model="filters.node_id" :placeholder="t('remote.nodeIdPlaceholder')" clearable />
        </el-form-item>
        <el-form-item :label="t('common.status')">
          <el-select v-model="filters.status" :placeholder="t('common.all')" clearable style="width: 120px">
            <el-option :label="t('remote.statusPending')" value="pending" />
            <el-option :label="t('remote.statusRunning')" value="running" />
            <el-option :label="t('common.success')" value="success" />
            <el-option :label="t('common.failed')" value="failed" />
            <el-option :label="t('remote.statusTimeout')" value="timeout" />
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="onSearch">{{ t('common.query') }}</el-button>
          <el-button @click="onResetFilter">{{ t('common.reset') }}</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <el-card>
      <DataTable
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :data="executions"
        :loading="loading"
        :server-side="false"
      >
        <el-table-column prop="execution_id" :label="t('remote.executionId')" min-width="180" />
        <el-table-column prop="node_id" :label="t('nodes.nodeId')" min-width="180" />
        <el-table-column prop="action_id" :label="t('remote.action')" min-width="140" />
        <el-table-column prop="status" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <StatusTag :status="row.status" type="task" />
          </template>
        </el-table-column>
        <el-table-column prop="timeout_seconds" :label="t('remote.timeoutSeconds')" width="100" />
        <el-table-column prop="created_at" :label="t('common.createdAt')" min-width="160">
          <template #default="{ row }">
            {{ row.created_at ? formatTime(row.created_at) : '-' }}
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="120" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" size="small" @click="showDetail(row)">
              {{ t('common.detail') }}
            </el-button>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <!-- 创建远程执行弹窗 -->
    <el-dialog v-model="dialogVisible" :title="t('remote.createDialogTitle')" width="600px">
      <el-form :model="form" label-width="100px" :rules="formRules" ref="formRef">
        <el-form-item :label="t('remote.targetNodes')" prop="node_ids">
          <el-select
            v-model="form.node_ids"
            multiple
            filterable
            :placeholder="t('remote.selectNodes')"
            style="width: 100%"
          >
            <el-option
              v-for="node in nodes"
              :key="node.node_id"
              :label="`${node.name} (${node.node_id})`"
              :value="node.node_id"
            />
          </el-select>
        </el-form-item>

        <el-form-item :label="t('remote.executeAction')" prop="action_id">
          <el-select
            v-model="form.action_id"
            :placeholder="t('remote.selectWhitelistAction')"
            style="width: 100%"
            @change="onActionChange"
          >
            <el-option
              v-for="action in remoteActions"
              :key="action.action_id"
              :label="`${actionDisplayName(action)} (${action.action_id})`"
              :value="action.action_id"
            />
          </el-select>
        </el-form-item>

        <el-form-item :label="t('remote.actionParams')" prop="action_params">
          <JsonEditor v-model="form.action_params" :rows="8" />
        </el-form-item>

        <el-form-item :label="t('remote.timeoutSeconds')" prop="timeout">
          <el-input-number v-model="form.timeout" :min="1" :max="3600" />
        </el-form-item>
      </el-form>

      <template #footer>
        <el-button @click="dialogVisible = false">{{ t('common.cancel') }}</el-button>
        <el-button type="primary" @click="onSubmit">{{ t('common.next') }}</el-button>
      </template>
    </el-dialog>

    <!-- 二次确认弹窗 -->
    <el-dialog v-model="confirmVisible" :title="t('remote.confirmDialogTitle')" width="520px">
      <el-alert
        :title="t('remote.confirmWarning')"
        type="warning"
        show-icon
        :closable="false"
        style="margin-bottom: 16px"
      />
      <p><strong>{{ t('remote.actionColon') }}</strong>{{ selectedActionName }}</p>
      <p><strong>{{ t('remote.nodeColon') }}</strong>{{ form.node_ids.join(', ') }}</p>
      <p><strong>{{ t('remote.timeoutColon') }}</strong>{{ form.timeout }} {{ t('common.seconds') }}</p>
      <p><strong>{{ t('remote.paramsColon') }}</strong></p>
      <CodeEditor v-model="confirmParamsJson" :rows="6" disabled />

      <template #footer>
        <el-button @click="confirmVisible = false">{{ t('common.cancel') }}</el-button>
        <el-button type="danger" :loading="submitting" @click="onConfirmExecute">{{ t('remote.confirmExecute') }}</el-button>
      </template>
    </el-dialog>

    <!-- 详情弹窗 -->
    <el-dialog v-model="detailVisible" :title="t('remote.detailDialogTitle')" width="680px">
      <el-descriptions :column="1" border>
        <el-descriptions-item :label="t('remote.executionId')">{{ currentExecution?.execution_id }}</el-descriptions-item>
        <el-descriptions-item :label="t('nodes.nodeId')">{{ currentExecution?.node_id }}</el-descriptions-item>
        <el-descriptions-item :label="t('remote.action')">{{ currentExecution?.action_id }}</el-descriptions-item>
        <el-descriptions-item :label="t('common.status')">
          <StatusTag v-if="currentExecution" :status="currentExecution.status" type="task" />
        </el-descriptions-item>
        <el-descriptions-item :label="t('remote.timeout')">{{ currentExecution?.timeout_seconds }} {{ t('common.seconds') }}</el-descriptions-item>
        <el-descriptions-item :label="t('remote.errorMessage')">{{ currentExecution?.error_message || '-' }}</el-descriptions-item>
      </el-descriptions>
      <div style="margin-top: 16px">
        <label>{{ t('remote.output') }}</label>
        <CodeEditor v-model="detailOutput" :rows="10" disabled />
      </div>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import { getNodes, type NodeRead } from '@/api/nodes'
import {
  createRemoteExecution,
  getRemoteActions,
  getRemoteExecution,
  listRemoteExecutions,
  type RemoteAction,
  type RemoteExecutionCreate,
  type RemoteExecutionRead,
} from '@/api/remoteExecution'
import StatusTag from '@/components/common/StatusTag.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import JsonEditor from '@/components/common/JsonEditor.vue'
import { actionDisplayName } from '@/utils/actionName'
import CodeEditor from '@/components/common/CodeEditor.vue'
import { showError } from '@/utils/error'

function formatTime(value: string | null | undefined): string {
  if (!value) return '-'
  const date = new Date(value)
  return date.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  })
}

const { t } = useI18n()
const authStore = useAuthStore()

const nodes = ref<NodeRead[]>([])
const remoteActions = ref<RemoteAction[]>([])
const executions = ref<RemoteExecutionRead[]>([])
const loading = ref(false)
const page = ref(1)
const pageSize = ref(10)

const dialogVisible = ref(false)
const confirmVisible = ref(false)
const detailVisible = ref(false)
const currentExecution = ref<RemoteExecutionRead | null>(null)
const submitting = ref(false)
const formRef = ref<FormInstance>()

const filters = reactive({
  node_id: '',
  status: '',
})

const form = reactive<RemoteExecutionCreate>({
  node_ids: [],
  action_id: '',
  action_params: {},
  timeout: 60,
  confirmed: false,
})

const formRules: FormRules = {
  node_ids: [
    { required: true, message: () => t('remote.selectNodesRequired'), trigger: 'change', type: 'array' },
  ],
  action_id: [{ required: true, message: () => t('remote.selectActionRequired'), trigger: 'change' }],
}

const selectedActionName = computed(() => {
  const action = remoteActions.value.find((a) => a.action_id === form.action_id)
  return action ? `${actionDisplayName(action)} (${action.action_id})` : form.action_id
})

const confirmParamsJson = computed(() => JSON.stringify(form.action_params, null, 2))

const detailOutput = computed(() => currentExecution.value?.output || '')

async function loadNodes() {
  try {
    const response = await getNodes({ page: 1, page_size: 100 })
    nodes.value = response.items
  } catch (error) {
    showError(error, t('remote.loadNodesFailed'))
  }
}

async function loadRemoteActions() {
  try {
    remoteActions.value = await getRemoteActions()
  } catch (error) {
    showError(error, t('remote.loadActionsFailed'))
  }
}

async function loadExecutions() {
  loading.value = true
  try {
    const params: { node_id?: string; status?: string } = {}
    if (filters.node_id) params.node_id = filters.node_id
    if (filters.status) params.status = filters.status
    executions.value = await listRemoteExecutions(params)
  } catch (error) {
    showError(error, t('remote.loadHistoryFailed'))
  } finally {
    loading.value = false
  }
}

function onCreate() {
  if (!authStore.isAdmin) {
    ElMessage.warning(t('remote.adminOnly'))
    return
  }
  form.node_ids = []
  form.action_id = ''
  form.action_params = {}
  form.timeout = 60
  form.confirmed = false
  dialogVisible.value = true
}

function onActionChange(actionId: string) {
  // 根据选中动作提供默认参数模板
  const templates: Record<string, Record<string, unknown>> = {
    restart_service: { service_name: 'nginx' },
    restart_container: { container_name: 'my-app' },
    clear_log: { log_path: '/var/log/app.log', keep_days: 7 },
    kill_process: { process_name: 'stuck-process' },
    run_script: { script_id: '', args: [] },
    view_logs: { log_path: '/var/log/app.log', lines: 100 },
    disk_usage: { path: '/' },
    service_status: { service_name: 'nginx' },
  }
  form.action_params = templates[actionId] || {}
}

async function onSubmit() {
  if (!formRef.value) return
  try {
    await formRef.value.validate()
    confirmVisible.value = true
  } catch {
    // 校验失败不继续
  }
}

async function onConfirmExecute() {
  submitting.value = true
  try {
    const result = await createRemoteExecution({
      ...form,
      confirmed: true,
    })
    ElMessage.success(t('remote.createdCount', { n: result.execution_ids.length }))
    confirmVisible.value = false
    dialogVisible.value = false
    loadExecutions()
  } catch (error) {
    showError(error, t('remote.createFailed'))
  } finally {
    submitting.value = false
  }
}

async function showDetail(row: RemoteExecutionRead) {
  try {
    currentExecution.value = await getRemoteExecution(row.execution_id)
    detailVisible.value = true
  } catch (error) {
    showError(error, t('remote.loadDetailFailed'))
  }
}

function onSearch() {
  page.value = 1
  loadExecutions()
}

function onResetFilter() {
  filters.node_id = ''
  filters.status = ''
  onSearch()
}

watch([page, pageSize], loadExecutions)

onMounted(() => {
  loadNodes()
  loadRemoteActions()
  loadExecutions()
})
</script>
